// launch-factory: 마이그레이션 적용. 사용법: DATABASE_URL=<직접 연결(5432)> node db/migrate.mjs
// 이 폴더의 migrations/ 를 순서대로 적용한다. 이미 적용한 파일은 건너뛴다(drizzle 기록 표).
import { fileURLToPath } from "node:url"
import postgres from "postgres"
import { drizzle } from "drizzle-orm/postgres-js"
import { migrate } from "drizzle-orm/postgres-js/migrator"

const url = process.env.DATABASE_URL
if (!url) {
  console.error("DATABASE_URL is not set")
  process.exit(1)
}
if (new URL(url).port === "6543") {
  console.error("Use the direct connection (port 5432) for migrations, not the transaction pooler (6543).")
  process.exit(1)
}

const client = postgres(url, { max: 1 })
try {
  await migrate(drizzle(client), { migrationsFolder: fileURLToPath(new URL("./migrations", import.meta.url)) })
  console.log("migrations applied")
} finally {
  await client.end()
}

import { headers } from "next/headers"
import { notFound } from "next/navigation"
import { realTossTestSession, tossTestConfig, tossTestService } from "@/lib/launch/toss-test"
import { TossTestButton } from "./toss-test-button"
import { TossTestCharge } from "./toss-test-charge"
import { TossTestControls } from "./toss-test-controls"
import { describeTossTestState } from "@/lib/toss-test-status"

export const dynamic = "force-dynamic"

export default async function TossTestPage({ searchParams }: { searchParams: Promise<{ registration?: string | string[] }> }) {
  const config = tossTestConfig()
  if (!config) notFound()
  const session = await realTossTestSession()
  const title = config.fake ? "모의 카드 등록" : "토스 시험 카드 등록"
  if (!session) return <section><h1>{title}</h1><p>실제 서버 계정으로 로그인해 주세요.</p></section>
  const service = await tossTestService()
  if (!service) notFound()
  const port = service.billing.port(session.userId)
  const resultState = await port.detail()
  const plans = await port.plans()
  if (!resultState.ok || !plans.ok || plans.data.length !== 1) return <section><h1>시험 구독</h1><p role="alert">상태를 확인할 수 없습니다.</p></section>
  const state = resultState.data
  const display = describeTossTestState(state)
  const result = (await searchParams).registration
  const nonce = (await headers()).get("x-nonce") ?? undefined
  return <section>
    <h1>{title}</h1>
    <p data-toss-auth="authenticated">서버 로그인 확인됨</p>
    <p>{config.fake ? "모의 등록 결과입니다." : "토스 테스트키를 사용하는 시험 등록입니다."} 실제 결제나 유료 기능 활성화는 하지 않습니다.</p>
    {result === "failed" && <p role="status">등록이 중단되었습니다. 기존 등록 요청이 만료된 뒤 다시 시작할 수 있습니다.</p>}
    {result === "unresolved" && <p role="status">등록 결과를 확인할 수 없습니다. 자동으로 다시 발급하지 않습니다.</p>}
    <p data-toss-state={state.paymentPending ? "payment-pending" : state.phase === "active" ? "charge-confirmed" : state.phase === "registered_unpaid" ? "registered-unpaid" : state.phase === "registering" ? "pending" : state.phase === "none" ? "not-registered" : state.phase}>
      {display.statusMessage}
    </p>
    {display.holdMessage && <p role="status">{display.holdMessage}</p>}
    {display.retryMessage && <p role="status">{display.retryMessage}</p>}
    {state.subscription.currentPeriodEnd && <p>시험 이용 종료: {state.subscription.currentPeriodEnd}</p>}
    {state.subscription.cancelAt && <p>이용 기간 끝 해지 예약됨</p>}
    {(state.phase === "none" || state.phase === "canceled") && !state.paymentPending && <TossTestButton clientKey={config.clientKey} fake={config.fake} nonce={nonce} />}
    {state.canChargeInitial && state.amount !== undefined && <TossTestCharge amount={state.amount} fake={config.fake} />}
    <TossTestControls pending={state.paymentPending} canCancel={state.registered} canCancelPeriod={state.canCancelPeriod} />
  </section>
}

"use client"

import Script from "next/script"
import { useState } from "react"
import { openTestBillingAuth, type TestBillingSdk } from "@/lib/toss-test-sdk-client"

declare global { interface Window { TossPayments?: (clientKey: string) => TestBillingSdk } }

export function TossTestButton({ clientKey, fake, nonce }: { clientKey: string; fake: boolean; nonce?: string }) {
  const [ready, setReady] = useState(fake)
  const [notice, setNotice] = useState("")
  const [busy, setBusy] = useState(false)
  async function start() {
    if ((!fake && typeof window.TossPayments !== "function") || busy) return
    setBusy(true)
    setNotice("")
    try {
      const response = await fetch("/api/toss/registration/start", { method: "POST", credentials: "same-origin" })
      const result: unknown = await response.json()
      if (!response.ok || typeof result !== "object" || result === null || !("status" in result) || result.status !== "ready" || !("customerKey" in result) || typeof result.customerKey !== "string" || !("successUrl" in result) || typeof result.successUrl !== "string" || !("failUrl" in result) || typeof result.failUrl !== "string") { setNotice("모의 등록을 시작할 수 없습니다. 기존 등록 또는 설정을 확인해 주세요."); return }
      const fakeSdk = (): TestBillingSdk => ({ payment: ({ customerKey }) => ({ requestBillingAuth: async ({ successUrl }) => {
        const url = new URL(successUrl)
        url.searchParams.set("customerKey", customerKey)
        url.searchParams.set("authKey", `fake_${crypto.randomUUID()}`)
        window.location.assign(url.toString())
      } }) })
      await openTestBillingAuth({ clientKey, customerKey: result.customerKey, successUrl: result.successUrl, failUrl: result.failUrl, origin: window.location.origin, sdk: fake ? fakeSdk : window.TossPayments as (key: string) => TestBillingSdk })
    } catch { setNotice("모의 등록창을 열지 못했습니다.") }
    finally { setBusy(false) }
  }
  return <>
    {!fake && <Script src="https://js.tosspayments.com/v2/standard" nonce={nonce} strategy="afterInteractive" onReady={() => { const available = typeof window.TossPayments === "function"; setReady(available); if (!available) setNotice("등록창을 불러오지 못했습니다.") }} onError={() => { setReady(false); setNotice("등록창을 불러오지 못했습니다.") }} />}
    <p id="toss-test-human">직접 확인하고 눌러 주세요.</p>
    <button type="button" disabled={!ready || busy} onClick={start} data-requires-human="checkout" aria-describedby="toss-test-human">{fake ? "모의 카드 등록" : "토스 시험 카드 등록"}</button>
    {notice && <p role="status">{notice}</p>}
  </>
}

"use client"

import { useRouter } from "next/navigation"
import { useState } from "react"

export function TossTestCharge({ amount, fake }: { amount: number; fake: boolean }) {
  const router = useRouter()
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState("")
  const mode = fake ? "모의" : "토스 시험"
  const unresolved = `${mode} 청구 결과를 확인할 수 없습니다. 자동으로 다시 승인하지 않습니다.`
  async function charge() {
    if (busy) return
    setBusy(true)
    try {
      const response = await fetch("/api/toss/test-charge", { method: "POST", credentials: "same-origin" })
      const result: unknown = await response.json()
      if (response.ok && typeof result === "object" && result !== null && "status" in result && result.status === "paid") setNotice(`${mode} 청구를 확인했습니다. 유료 권한은 활성화되지 않습니다.`)
      else if (response.ok && typeof result === "object" && result !== null && "status" in result && result.status === "declined") setNotice(`${mode} 청구가 거절되었습니다. 다시 시도할 수 있는 시각을 확인해 주세요.`)
      else setNotice(unresolved)
      router.refresh()
    } catch { setNotice(unresolved) }
    finally { setBusy(false) }
  }
  return <><button type="button" disabled={busy} onClick={charge} data-requires-human="checkout">{mode} 첫 청구 확인 ({new Intl.NumberFormat("ko-KR").format(amount)}원, 실제 결제 없음)</button>{notice && <p role="status">{notice}</p>}</>
}

"use client"
import { useRouter } from "next/navigation"
import { useState } from "react"

export function TossTestControls({ pending, canCancel, canCancelPeriod }: { pending: boolean; canCancel: boolean; canCancelPeriod: boolean }) {
  const router = useRouter()
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState("")
  async function act(action: "reconcile" | "cancel_now" | "cancel_period") {
    if (busy) return
    setBusy(true)
    try {
      const response = await fetch("/api/toss/test-subscription", { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, confirmed: true }) })
      const result: unknown = await response.json()
      if (!response.ok || typeof result !== "object" || result === null || !("ok" in result) || result.ok !== true || !("data" in result) || typeof result.data !== "object" || result.data === null) {
        setNotice("상태를 확인하지 못했습니다. 다시 승인하지 않습니다.")
      } else if (action === "reconcile") {
        if (!("paymentPending" in result.data) || typeof result.data.paymentPending !== "boolean") setNotice("상태를 확인하지 못했습니다. 다시 승인하지 않습니다.")
        else if (result.data.paymentPending) setNotice("기존 주문은 아직 확인되지 않았습니다. 다시 승인하지 않습니다.")
        else setNotice("기존 주문의 확인 결과를 화면에 반영했습니다.")
      } else if (pending) setNotice("해지 요청을 접수했습니다. 기존 주문 결과를 확인 중입니다.")
      else setNotice("시험 구독 상태를 변경했습니다.")
      router.refresh()
    } catch { setNotice("상태를 확인하지 못했습니다. 다시 승인하지 않습니다.") }
    finally { setBusy(false) }
  }
  return <>
    {pending && <button type="button" disabled={busy} onClick={() => act("reconcile")}>기존 주문 확인</button>}
    {canCancel && <button type="button" disabled={busy} onClick={() => act("cancel_now")} data-requires-human="cancel">시험 구독 즉시 해지</button>}
    {canCancelPeriod && <button type="button" disabled={busy} onClick={() => act("cancel_period")} data-requires-human="cancel">이용 기간 끝에 해지</button>}
    {notice && <p role="status">{notice}</p>}
  </>
}

import { realTossTestSession, tossTestService } from "@/lib/launch/toss-test"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function POST(request: Request) {
  const headers = { "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" }
  try {
    const service = await tossTestService()
    if (!service) return Response.json({ status: "unavailable" }, { status: 404, headers })
    if (request.headers.get("origin") !== service.config.origin) return Response.json({ status: "invalid" }, { status: 403, headers })
    const session = await realTossTestSession()
    if (!session) return Response.json({ status: "unauthorized" }, { status: 401, headers })
    const checkout = await service.billing.port(session.userId).checkout({ planId: "test-monthly" })
    if (!checkout.ok) return Response.json({ status: "unavailable" }, { status: 409, headers })
    const result = await service.endpoints.begin(request, "test-monthly")
    return Response.json(result, { status: result.status === "unauthorized" ? 401 : result.status === "invalid" ? 403 : 200, headers })
  } catch { return Response.json({ status: "unavailable" }, { status: 503, headers }) }
}

import { tossTestService } from "@/lib/launch/toss-test"
import { canonicalTossCallback } from "@/lib/toss-test-url"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  try {
    const service = await tossTestService()
    if (!service) return new Response(null, { status: 404, headers: { "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" } })
    const canonical = canonicalTossCallback(request, service.config.origin, "/api/toss/registration/complete")
    if (!canonical) return new Response(null, { status: 400, headers: { "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" } })
    const response = await service.endpoints.complete(canonical)
    if (response.status !== 303) return response
    const result = new URL(response.headers.get("location") as string).searchParams.get("registration")
    const target = new URL("/account/billing/toss-test", service.config.origin)
    target.searchParams.set("registration", ["registered", "canceled", "unresolved", "invalid"].includes(result ?? "") ? result as string : "invalid")
    return new Response(null, { status: 303, headers: { "Location": target.toString(), "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" } })
  } catch { return new Response(null, { status: 503, headers: { "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" } }) }
}

import { realTossTestSession, tossTestService } from "@/lib/launch/toss-test"
import { canonicalTossCallback } from "@/lib/toss-test-url"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  const headers = { "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" }
  try {
    const service = await tossTestService()
    if (!service) return new Response(null, { status: 404, headers })
    const session = await realTossTestSession()
    if (!session) return new Response(null, { status: 401, headers })
    const canonical = canonicalTossCallback(request, service.config.origin, "/api/toss/registration/fail")
    if (!canonical) return new Response(null, { status: 400, headers })
    const url = new URL(canonical.url)
    const states = url.searchParams.getAll("state")
    if (states.length !== 1) return new Response(null, { status: 400, headers })
    const status = await service.registration.status({ userId: session.userId, state: states[0] })
    const target = new URL("/account/billing/toss-test", service.config.origin)
    target.searchParams.set("registration", status === "pending" ? "failed" : "invalid")
    // 실패 URL은 구독을 바꾸지 않는다. 만료 전 재진입은 기존 세션이 막는다.
    return new Response(null, { status: 303, headers: { ...headers, Location: target.toString() } })
  } catch { return new Response(null, { status: 503, headers }) }
}

import { realTossTestSession, tossTestService } from "@/lib/launch/toss-test"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

// 개발용 시험 모드만 허용한다. 요청에서 금액·상품·사용자를 받지 않는다.
export async function POST(request: Request) {
  const headers = { "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" }
  try {
    const service = await tossTestService()
    if (!service) return Response.json({ status: "unavailable" }, { status: 404, headers })
    if (request.headers.get("origin") !== service.config.origin) return Response.json({ status: "invalid" }, { status: 403, headers })
    const session = await realTossTestSession()
    if (!session) return Response.json({ status: "unauthorized" }, { status: 401, headers })
    const rows = await service.db.query<{ id: string }>("SELECT id FROM toss_ledger_subscriptions WHERE user_id=$1 AND product_id=$2 AND status='enabled'", [session.userId, service.productId])
    if (rows.rows.length !== 1) return Response.json({ status: "not_claimed" }, { status: 409, headers })
    const status = await service.ledger.chargeInitial(rows.rows[0].id, session.userId)
    return Response.json({ status }, { status: status === "not_claimed" ? 409 : 200, headers })
  } catch { return Response.json({ status: "unavailable" }, { status: 503, headers }) }
}

import { realTossTestSession, tossTestService } from "@/lib/launch/toss-test"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"
const headers = { "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" }

export async function POST(request: Request) {
  try {
    const service = await tossTestService()
    if (!service) return Response.json({ status: "unavailable" }, { status: 404, headers })
    if (request.headers.get("origin") !== service.config.origin) return Response.json({ status: "invalid" }, { status: 403, headers })
    const session = await realTossTestSession()
    if (!session) return Response.json({ status: "unauthorized" }, { status: 401, headers })
    const input: unknown = await request.json()
    if (typeof input !== "object" || input === null || !("action" in input)) return Response.json({ status: "invalid" }, { status: 400, headers })
    const port = service.billing.port(session.userId)
    const result = input.action === "reconcile" ? await port.reconcile() : input.action === "cancel_now" || input.action === "cancel_period" ? await port.cancel({ when: input.action === "cancel_now" ? "now" : "period_end", confirmed: "confirmed" in input && input.confirmed === true ? true : undefined }) : null
    if (!result) return Response.json({ status: "invalid" }, { status: 400, headers })
    return Response.json(result, { status: result.ok ? 200 : 409, headers })
  } catch { return Response.json({ status: "unavailable" }, { status: 503, headers }) }
}

// 실제 Better Auth 세션과 탈퇴 확인 규칙을 통과하는 개발 시험 전용 입구다.
import { authActions } from "@launch-factory/auth"
import { accountPort } from "@/lib/launch/account"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { realTossTestSession, tossTestConfig } from "@/lib/launch/toss-test"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"
export async function POST(request: Request) {
  const headers = { "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" }
  const config = tossTestConfig()
  if (!config) return Response.json({ status: "unavailable" }, { status: 404, headers })
  if (request.headers.get("origin") !== config.origin) return Response.json({ status: "invalid" }, { status: 403, headers })
  try {
    if (!(await realTossTestSession())) return Response.json({ status: "unauthorized" }, { status: 401, headers })
    const input: unknown = await request.json()
    const result = await authActions(await accountPort(), { locale: DEFAULT_LOCALE }).deleteAccount(input)
    return Response.json(result.ok ? { status: "requested" } : { status: "unavailable" }, { status: result.ok ? 200 : 400, headers })
  } catch { return Response.json({ status: "unavailable" }, { status: 503, headers }) }
}

import { handleTestTossCron } from "@launch-factory/billing-toss"
import { cronAuthorized, unauthorized } from "@/lib/launch/cron"
import { tossTestService } from "@/lib/launch/toss-test"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  if (!cronAuthorized(request)) return unauthorized()
  return await handleTestTossCron(request, cronAuthorized, tossTestService)
}

// 토스가 꺼져 있어도 기존 원장은 삭제 확인 전까지 계정 파기를 막는다.
import { blockTossForDeletion, collectTossRetention, prepareTossDeletion, purgeTossData } from "@launch-factory/billing-toss"
import type { Database } from "@launch-factory/db"
import type { Purger, PurgePreparation, RetentionCollector } from "@launch-factory/account-lifecycle"
import { tossTestConnection, tossTestDatabase } from "./toss-test-db.ts"

type Tx = Parameters<Parameters<Database["transaction"]>[0]>[0]
export const blockTossDeletion = async (tx: Tx, userId: string) => {
  try { await blockTossForDeletion(tossTestConnection(tx), userId) }
  catch { throw new Error("Toss deletion storage failure") }
}
/** 본인 요금제·금액·상태·기간만 선택한다. 결제 식별자와 암호문은 읽지 않는다. */
export async function exportTossData(db: Database, userId: string) {
  const rows = await tossTestDatabase(db).query<{ plan_id: string; amount: number; status: string; created_at: Date; period_start: Date | null; period_end: Date | null; cancel_at: Date | null; next_due_at: Date | null }>("SELECT plan_id,amount,status,created_at,period_start,period_end,cancel_at,next_due_at FROM toss_ledger_subscriptions WHERE user_id=$1 ORDER BY created_at,id", [userId])
  const iso = (date: Date | null) => date ? new Date(date).toISOString() : null
  return rows.rows.map((row) => ({ provider: "toss" as const, planId: row.plan_id, amount: row.amount, currency: "KRW" as const, status: row.status, createdAt: iso(row.created_at), currentPeriodStart: iso(row.period_start), currentPeriodEnd: iso(row.period_end), cancelAt: iso(row.cancel_at), nextDueAt: iso(row.next_due_at) }))
}
export const tossCollector: RetentionCollector = (tx, ctx) => collectTossRetention(tossTestConnection(tx), ctx.userId, ctx.now)
export const tossPurger: Purger = (tx, ctx) => purgeTossData(tossTestConnection(tx), ctx.userId)

export async function prepareTossPurge(db: Database, userId: string): Promise<PurgePreparation> {
  try {
    const adapter = tossTestDatabase(db)
    if ((await adapter.query("SELECT 1 FROM toss_registration_sessions WHERE user_id=$1 AND status IN ('issuing','cancel_requested') LIMIT 1", [userId])).rows.length) return "registration_unresolved"
    const unsafe = await adapter.query<{ product_id: string }>("SELECT DISTINCT s.product_id FROM toss_ledger_subscriptions s WHERE s.user_id=$1 AND (s.status<>'canceled' OR s.encrypted_billing_key IS NOT NULL OR EXISTS (SELECT 1 FROM toss_ledger_charges c WHERE c.subscription_id=s.id AND c.status='in_flight'))", [userId])
    if (!unsafe.rows.length) return "ready"
    const { tossTestService } = await import("./toss-test.ts")
    const service = await tossTestService()
    if (!service || unsafe.rows.some((row) => row.product_id !== service.productId)) return "provider_unavailable"
    return prepareTossDeletion(adapter, service.ledger, userId)
  } catch { return "storage_unavailable" }
}

// 시험 등록 패키지의 SQL 계약을 기존 Drizzle DB에 연결한다. 값은 모두 바인딩한다.
import { sql, type SQL } from "drizzle-orm"
import type { Database } from "@launch-factory/db"
import type { LedgerDatabase, SqlConnection } from "@launch-factory/billing-toss"

function boundQuery(text: string, params: unknown[]): SQL {
  const query = sql.empty()
  let end = 0
  for (const match of text.matchAll(/\$(\d+)/g)) {
    query.append(sql.raw(text.slice(end, match.index)))
    const index = Number(match[1]) - 1
    if (index < 0 || index >= params.length) throw new Error("Invalid query binding")
    // postgres-js의 raw SQL 바인딩은 Date를 인코딩하지 않으므로 ISO 문자열로 전달한다.
    const value = params[index] instanceof Date ? params[index].toISOString() : params[index]
    query.append(sql`${value}`)
    end = (match.index ?? 0) + match[0].length
  }
  query.append(sql.raw(text.slice(end)))
  return query
}

export function tossTestConnection(db: Database): SqlConnection {
  return {
    async query<T extends Record<string, unknown>>(text: string, params: unknown[] = []): Promise<{ rows: T[] }> {
      const result = await db.execute(boundQuery(text, params))
      const rows = Array.isArray(result) ? result : (result as unknown as { rows: unknown[] }).rows
      return { rows: rows as T[] }
    },
  }
}

export function tossTestDatabase(db: Database): LedgerDatabase {
  return {
    ...tossTestConnection(db),
    transaction: (run) => db.transaction((tx) => run(tossTestConnection(tx)), { isolationLevel: "read committed" }),
  }
}

